// Generated by CodeGen serialization emitter for codegen_containers::Containers.
// Requires: the type is defined + CodeGenMeta.h + Serialization.h on the include path.
// Deterministic: declaration-order field traversal, same input => same bytes.
// Unordered containers are flattened and sorted before writing (task 3.1), and every
// container is cleared before reading (task 3.4), so the bytes and the read-back result
// depend on the CONTENT only — never on the insertion history of the container.
#pragma once

#include "CodeGenMeta.h"
#include "Serialization.h"
#include <algorithm>   // std::sort for the canonical container order
#include <utility>     // std::pair for the flattened map entries
#include <type_traits> // the container traits below
#include <vector>      // the flattened array itself

namespace cacore::codegen
{
template<typename T, typename = void> struct CGIsUnordered : std::false_type {};
template<typename T> struct CGIsUnordered<T, std::void_t<decltype(std::declval<T const&>().bucket_count())>> : std::true_type {};
template<typename T, typename = void> struct CGIsMapLike : std::false_type {};
template<typename T> struct CGIsMapLike<T, std::void_t<typename T::mapped_type>> : std::true_type {};
template<typename T> struct CGIsContainer
    : std::integral_constant<bool, careflection::containerStates<T>::is_container_with_size> {};
// map/set expose pair<const K, V>: the flattened array needs an assignable element
template<typename T, typename = void> struct CGFlat { using type = T; };
template<typename T> struct CGFlat<T, std::void_t<typename T::first_type, typename T::second_type>>
{
    using type = std::pair<std::remove_const_t<typename T::first_type>, typename T::second_type>;
};

template<typename ByteBuffer, typename E> void cgWriteValue(::cacore::serializer<ByteBuffer>& s, E const& e);
template<typename ByteBuffer, typename E> void cgReadValue(::cacore::deserializer<ByteBuffer>& d, E& e);
template<typename ByteBuffer, typename C> void cgWriteContainer(::cacore::serializer<ByteBuffer>& s, C const& c);
template<typename ByteBuffer, typename C> void cgReadContainer(::cacore::deserializer<ByteBuffer>& d, C& c);

// Writes the element count, then every element - sorted first when the container's traversal
// order is unspecified, so the bytes depend on the CONTENT only.
template<typename ByteBuffer, typename C>
void cgWriteContainerSized(::cacore::serializer<ByteBuffer>& s, C const& c)
{
    using E0 = typename C::value_type;
    using E = typename CGFlat<E0>::type;  // map value_type carries a const key
    if constexpr (CGIsUnordered<C>::value)
    {
        std::vector<E> flat(c.begin(), c.end());
        std::sort(flat.begin(), flat.end(), [](E const& a, E const& b) {
            if constexpr (CGIsMapLike<C>::value) return a.first < b.first;
            else return a < b; });
        s.serialize(static_cast<unsigned long long>(flat.size()));
        for (auto const& e : flat) cgWriteValue(s, e);
    }
    else
    {
        s.serialize(static_cast<unsigned long long>(c.size()));
        for (auto const& e : c) cgWriteValue(s, e);
    }
}

// C arrays (including every extra dimension) are written as (extent, elements), which is exactly
// the multi-dimension shape the disk contract describes.
template<typename ByteBuffer, typename C>
void cgWriteContainer(::cacore::serializer<ByteBuffer>& s, C const& c)
{
    if constexpr (std::is_array_v<C>)
    {
        s.serialize(static_cast<unsigned long long>(std::extent_v<C>));
        for (auto const& e : c) cgWriteValue(s, e);
    }
    else cgWriteContainerSized(s, c);
}

template<typename ByteBuffer, typename E>
void cgWriteValue(::cacore::serializer<ByteBuffer>& s, E const& e)
{
    if constexpr (std::is_array_v<E>) cgWriteContainer(s, e);
    else if constexpr (CGIsContainer<E>::value) cgWriteContainer(s, e);
    else if constexpr (CGIsMapLike<std::remove_cv_t<E>>::value == false && requires { e.first; e.second; })
    { cgWriteValue(s, e.first); cgWriteValue(s, e.second); }
    else s.serialize(e);
}

// Clears the target first, then rebuilds it from the payload alone: the result must depend on the
// payload only, never on whatever the target happened to hold before.
template<typename ByteBuffer, typename C>
void cgReadContainerSized(::cacore::deserializer<ByteBuffer>& d, C& c)
{
    c.clear();
    unsigned long long n = 0;
    d.deserialize(n);
    for (unsigned long long i = 0; i < n; ++i)
    {
        using E = typename C::value_type;
        if constexpr (CGIsMapLike<C>::value)
        {
            using K = std::remove_const_t<typename E::first_type>;
            using V = typename E::second_type;
            K k{}; V v{}; cgReadValue(d, k); cgReadValue(d, v);
            c.insert(std::make_pair(std::move(k), std::move(v)));
        }
        else
        {
            E e{}; cgReadValue(d, e); c.insert(c.end(), std::move(e));
        }
    }
}

template<typename ByteBuffer, typename C>
void cgReadContainer(::cacore::deserializer<ByteBuffer>& d, C& c)
{
    if constexpr (std::is_array_v<C>)
    {
        unsigned long long n = 0;
        d.deserialize(n);
        for (unsigned long long i = 0; i < n && i < std::extent_v<C>; ++i) cgReadValue(d, c[i]);
    }
    else cgReadContainerSized(d, c);
}

template<typename ByteBuffer, typename E>
void cgReadValue(::cacore::deserializer<ByteBuffer>& d, E& e)
{
    if constexpr (std::is_array_v<E>) cgReadContainer(d, e);
    else if constexpr (CGIsContainer<E>::value) cgReadContainer(d, e);
    else if constexpr (requires { e.first; e.second; })
    { cgReadValue(d, e.first); cgReadValue(d, e.second); }
    else d.deserialize(e);
}

template<typename T> struct CodeGenSerializer;  // primary template

template<>
struct CodeGenSerializer<codegen_containers::Containers>
{
    using Obj = codegen_containers::Containers;
    template<typename ByteBuffer>
    static void serialize(Obj const& obj, ByteBuffer& buffer)
    {
        ::cacore::serializer<ByteBuffer> s(buffer);  // one instance carries offset
        cgWriteContainer(s, obj.vec);
        cgWriteContainer(s, obj.umap);
        cgWriteContainer(s, obj.omap);
        cgWriteContainer(s, obj.oset);
        cgWriteContainer(s, obj.uset);
        cgWriteContainer(s, obj.nested);
        cgWriteContainer(s, obj.vecOfUmap);
        cgWriteContainer(s, obj.umapOfUmap);
        cgWriteContainer(s, obj.umaps);
        cgWriteContainer(s, obj.floatMap);
        cgWriteContainer(s, obj.floats);
        cgWriteContainer(s, obj.grid);
        cgWriteContainer(s, obj.label);
        s.serialize(obj.plain);
    }
    template<typename ByteBuffer>
    static void deserialize(Obj& obj, ByteBuffer const& buffer)
    {
        ::cacore::deserializer<ByteBuffer> d(buffer);  // one instance carries offset
        cgReadContainer(d, obj.vec);
        cgReadContainer(d, obj.umap);
        cgReadContainer(d, obj.omap);
        cgReadContainer(d, obj.oset);
        cgReadContainer(d, obj.uset);
        cgReadContainer(d, obj.nested);
        cgReadContainer(d, obj.vecOfUmap);
        cgReadContainer(d, obj.umapOfUmap);
        cgReadContainer(d, obj.umaps);
        cgReadContainer(d, obj.floatMap);
        cgReadContainer(d, obj.floats);
        cgReadContainer(d, obj.grid);
        cgReadContainer(d, obj.label);
        d.deserialize(obj.plain);
    }
};
} // namespace cacore::codegen
